  "landing.aria": "Fikarohana lehibe", "landing.kicker": "FITAOVANA HO AN’NY GAZETY · MADAGASIKARA", "landing.titleA": "Haingana ny fielezan’ny tsaho.", "landing.titleB": "Tokony hanaraka ny fanitsiana.", "landing.description": "Ampifandraisin’i Laverta ny fampandrenesana sy ny asa fanamarinana ataon’ny mpanao gazety, mba ho mora hita indray ny fanitsiana.", "landing.reportCta": "Hampandre vaovao", "landing.trackCta": "Hijery raharaha", "landing.methodCta": "Hijery ny fomba fiasa", "landing.human": "Fitaovana manampy. Olona no manapa-kevitra.",
  "landing.artAria": "Sary Laverta: globe misy teboka, làlan’ny loharano ary mascotte mitazona fitaratra fanalehibeazana", "landing.artExample": "OHATRA RAHARAHA", "landing.artContext": "MBOLA HAZAVAINA NY TOE-JAVATRA", "landing.artFiction": "SARY FORONINA", "landing.artImage": "SARY · OHATRA", "landing.artSignal": "VAOVAO VOARAY", "landing.artRoute": "LOHARANO", "landing.artContextShort": "TOE-JAVATRA", "landing.artCrosscheck": "HAMPIFANARAHINA", "landing.artStep1": "DINGANA 01 · FAMPANDRENESANA", "landing.artQuestion": "Antsipiriany hojerena", "landing.artSource": "Tokony hojerena ny loharano.", "landing.artStep3": "DINGANA 03 · FAMARANANA", "landing.artHuman": "Fanapahan-kevitry ny olona", "landing.artEditor": "Ny mpanao gazety no manapa-kevitra farany.", "landing.artCaption": "SARY FANAZAVANA · ANGON-DRONONO FORONINA",
  "landing.ribbonAria": "Dingana amin’ny fomba fiasa", "landing.stepSpot": "MAHATSIKARITRA", "landing.stepCrosscheck": "MAMPIFANARAKA", "landing.stepQualify": "MANDINIKA", "landing.stepCirculate": "MAMPIELY FANITSIANA", "intro.skip": "Handingana", "landing.methodKicker": "ROHY IRAY · DINGANA TELO", "landing.methodTitleA": "Manomboka amin’ny fampandrenesana", "landing.methodTitleB": "ka hatramin’ny fanitsiana.", "landing.methodDescription": "Tian’i Laverta hahena ny elanelana eo amin’ny vaovao ampandrenesina, ny fanamarinana azy ary ny fanitsiana mora hita.",
  "landing.card1Title": "Mahita mialoha", "landing.card1Text": "Manampy ny efitrano famoaham-baovao hahita ireo lohahevitra mila jerena haingana ny fampandrenesana.", "landing.card2Title": "Mampifanaraka amim-pitandremana", "landing.card2Text": "Alamin’i Laverta ny porofo. Ny mpanao gazety no mijery ny loharano sy mifidy ny dingana manaraka.", "landing.card3Title": "Mampita ny fanitsiana", "landing.card3Text": "Afaka jerena indray ny fanitsiana voamarina ary zarain’ny mpitarika eny an-toerana.", "landing.prototypeLabel": "Misy amin’ny prototype:", "landing.prototypeText": "mandefa sary na rohy, mahazo kaody LV, mijery ny satan’ny raharaha ary mamaky fanitsiana navoakan’ny mpanao gazety.",
  "landing.editorRule": "NY MPANAO GAZETY NO MANAPA-KEVITRA FARANY", "landing.proofTitle": "Porofo aloha.", "landing.correctionTitle": "Avy eo ny fanitsiana.", "landing.aiNote": "Afaka manampy mandamina fampandrenesana sy manomana hevitra ny AI. Ny mpanao gazety no manamarina loharano, misafidy didy ary mankato ny hafatra avoaka.", "landing.sourceTitle": "Hita sy azo jerena ny loharano", "landing.sourceText": "Tokony hitondra any amin’ny loharano azo sokafana sy ampitahaina ny hevitra iray.", "landing.uncertaintyTitle": "Hazavaina ny tsy fahazoana antoka", "landing.uncertaintyText": "Raha tsy ampy ny porofo dia mbola dinihina ny raharaha. Tsy midika ho marina ny tombana.", "landing.privacyTitle": "Arovana ny olona", "landing.privacyText": "Tsy azon’ny daholobe jerena ny fampandrenesana; tsy aseho amin’ny fanitsiana navoaka ny mombamomba ny mpampandre.",
  "landing.mobileKicker": "NATAO HO AN’NY ENY AN-TSEHANA", "landing.mobileTitleA": "Ny asa eny an-toerana", "landing.mobileTitleB": "ao am-paosy.", "landing.mobileText": "Efa mifanaraka amin’ny finday ny tranonkala. Kasaina ny APK sy ny fizarana mivantana, saingy mbola miandry rohy famoahana ampahibemaso.", "landing.apkPreparing": "Mbola amboarina ny APK", "landing.apkAfter": "Hita rehefa avoaka", "landing.ctaKicker": "LAVERTA · URBIX", "landing.ctaTitleA": "Miely ny tsaho.", "landing.ctaTitleB": "Miely koa ny fanitsiana.", "landing.ctaText": "Jereo ny prototype sy ny fomba fanamarinana natao ho an’ny mpanao gazety sy ny vondrom-piarahamonina eto Madagasikara.", "landing.footerCopyright": "© 2026 URBIX · ANTANANARIVO", "landing.backTop": "Hiverina eny ambony ↑",
