export const dictionaries: Record<Locale, Record<Keys, string>> = { fr, en, mg };

export function normalizeLocale(value: unknown): Locale {
  return locales.includes(value as Locale) ? (value as Locale) : "fr";
}

export function translate(locale: Locale, key: Keys, values?: Record<string, string | number>) {
  // Un texte encore vide dans une langue s’affiche en français plutôt que blanc.
  let message = dictionaries[locale][key] || fr[key];
  if (values) {
    for (const [name, value] of Object.entries(values)) message = message.replaceAll(`{${name}}`, String(value));
  }
  return message;
}
